#include <stddef.h>
#include <stdint.h>
#define BAD (-1.0e300)
double jaro_winkler(const int64_t*v,size_t n){if(!v||n<2||n>66)return BAD;int64_t n1=v[0];if(n1<0||n1>32||1+(size_t)n1>=n)return BAD;size_t p2=1+(size_t)n1;int64_t n2=v[p2];if(n2<0||n2>32||n!=p2+1+(size_t)n2)return BAD;for(size_t i=0;i<(size_t)n1;i++)if(v[1+i]<0||v[1+i]>127)return BAD;for(size_t j=0;j<(size_t)n2;j++)if(v[p2+1+j]<0||v[p2+1+j]>127)return BAD;int s1[32],s2[32];for(int i=0;i<n1;i++)s1[i]=(int)v[1+i];for(int j=0;j<n2;j++)s2[j]=(int)v[p2+1+j];const int radius=(n1<n2?n1:n2)/2;int used1[32]={0},used2[32]={0},a[32],b[32],ma=0,mb=0;for(int i=0;i<n1;i++){int lo=i-radius;if(lo<0)lo=0;int hi=i+radius+1;if(hi>n2)hi=n2;for(int j=lo;j<hi;j++)if(!used2[j]&&s1[i]==s2[j]){used2[j]=1;a[ma++]=s1[i];break;}}for(int i=0;i<n2;i++){int lo=i-radius;if(lo<0)lo=0;int hi=i+radius+1;if(hi>n1)hi=n1;for(int j=lo;j<hi;j++)if(!used1[j]&&s2[i]==s1[j]){used1[j]=1;b[mb++]=s2[i];break;}}int trans=0;for(int i=0;i<ma&&i<mb;i++)if(a[i]!=b[i])trans++;trans/=2;double jaro=0.0;if(ma)jaro=((double)ma/n1+(double)ma/n2+(double)(ma-trans)/ma)/3.0;int prefix=0;while(prefix<4&&prefix<n1&&prefix<n2&&s1[prefix]==s2[prefix])prefix++;return jaro+0.1*(double)prefix*(1.0-jaro);}
